WITH car AS (SELECT REPLACE(id_imovel,'-','') id_car_norm,id_municipio FROM `basedosdados.br_sfb_sicar.area_imovel` WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),pl AS (SELECT DISTINCT id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao=2023 AND id_car IS NOT NULL AND TRIM(id_car)!=''),onum AS (SELECT id_referencia_bacen,numero_ordem,COUNT(*) n FROM pl GROUP BY 1,2),credit AS (SELECT c.id_municipio,SUM(op.valor_parcela_credito/onum.n) credito FROM `basedosdados.br_bcb_sicor.operacao` op JOIN onum USING(id_referencia_bacen,numero_ordem) JOIN pl USING(id_referencia_bacen,numero_ordem) JOIN car c USING(id_car_norm) WHERE op.ano_emissao=2023 GROUP BY 1),top20 AS (SELECT id_municipio FROM (SELECT id_municipio,ROW_NUMBER() OVER(ORDER BY credito DESC) r FROM credit) WHERE r<=20),pop AS (SELECT id_municipio,populacao FROM `basedosdados.br_ibge_populacao.municipio` WHERE ano=2023),pib AS (SELECT id_municipio,pib FROM `basedosdados.br_ibge_pib.municipio` WHERE ano=2023),va AS (SELECT id_municipio,va_agropecuaria FROM `basedosdados.br_ibge_pib.municipio` WHERE ano=2021),re AS (SELECT id_municipio,SUM(quantidade_vinculos_ativos) empregos_total,SUM(IF(SUBSTR(cnae_2,1,2) IN ('01','02','03'),quantidade_vinculos_ativos,0)) empregos_agro FROM `basedosdados.br_me_rais.microdados_estabelecimentos` WHERE ano=2023 GROUP BY id_municipio),rs AS (SELECT id_municipio,AVG(valor_remuneracao_media) remuneracao_media FROM `basedosdados.br_me_rais.microdados_vinculos` WHERE ano=2023 AND vinculo_ativo_3112='1' GROUP BY id_municipio),sc AS (SELECT id_municipio,SUM(IF(id_conta_bd='1.1.1.0.0.00.00.00' AND estagio_bd='Receitas Brutas Realizadas',valor,0)) receita_tributaria,SUM(IF(id_conta_bd='1.1.7.0.0.00.00.00' AND estagio_bd='Receitas Brutas Realizadas',valor,0)) transferencias FROM `basedosdados.br_me_siconfi.municipio_receitas_orcamentarias` WHERE ano=2023 GROUP BY id_municipio),nasc AS (SELECT id_municipio_residencia id_municipio,COUNT(*) nascidos FROM `basedosdados.br_ms_sinasc.microdados` WHERE ano=2023 GROUP BY 1),ob AS (SELECT id_municipio_residencia id_municipio,COUNT(*) obitos FROM `basedosdados.br_ms_sim.microdados` WHERE ano=2023 AND idade<1 GROUP BY 1),sa AS (SELECT n.id_municipio,SAFE_MULTIPLY(SAFE_DIVIDE(ob.obitos,n.nascidos),1000) mortalidade_infantil FROM nasc n LEFT JOIN ob USING(id_municipio)),idb AS (SELECT id_municipio,MAX(IF(rede='publica' AND ensino='fundamental' AND anos_escolares='iniciais (1-5)',ideb,NULL)) ideb_iniciais,MAX(IF(rede='publica' AND ensino='fundamental' AND anos_escolares='finais (6-9)',ideb,NULL)) ideb_finais FROM `basedosdados.br_inep_ideb.municipio` WHERE ano=2023 GROUP BY id_municipio),b AS (SELECT m.id_municipio,IF(t.id_municipio IS NOT NULL,'top20_credito','demais_municipios') grupo,SAFE_DIVIDE(c.credito,pop.populacao) credito_pc,SAFE_DIVIDE(pib.pib,pop.populacao) pib_pc,SAFE_DIVIDE(va.va_agropecuaria,pop.populacao) va_agro_pc,re.empregos_total,re.empregos_agro,SAFE_DIVIDE(re.empregos_agro,re.empregos_total) agro_share,rs.remuneracao_media,SAFE_DIVIDE(sc.receita_tributaria,pop.populacao) tributo_pc,SAFE_DIVIDE(sc.transferencias,pop.populacao) transfer_pc,sa.mortalidade_infantil,idb.ideb_iniciais,idb.ideb_finais FROM `basedosdados.br_bd_diretorios_brasil.municipio` m LEFT JOIN credit c USING(id_municipio) LEFT JOIN top20 t USING(id_municipio) LEFT JOIN pop USING(id_municipio) LEFT JOIN pib USING(id_municipio) LEFT JOIN va USING(id_municipio) LEFT JOIN re USING(id_municipio) LEFT JOIN rs USING(id_municipio) LEFT JOIN sc USING(id_municipio) LEFT JOIN sa USING(id_municipio) LEFT JOIN idb USING(id_municipio)) SELECT grupo,COUNT(*) municipios,AVG(credito_pc) media_credito_pc,APPROX_QUANTILES(credito_pc,100 IGNORE NULLS)[OFFSET(50)] mediana_credito_pc,AVG(pib_pc) media_pib_pc,APPROX_QUANTILES(pib_pc,100 IGNORE NULLS)[OFFSET(50)] mediana_pib_pc,AVG(va_agro_pc) media_va_agro_pc,APPROX_QUANTILES(va_agro_pc,100 IGNORE NULLS)[OFFSET(50)] mediana_va_agro_pc,AVG(empregos_total) media_empregos_total,APPROX_QUANTILES(empregos_total,100 IGNORE NULLS)[OFFSET(50)] mediana_empregos_total,AVG(empregos_agro) media_empregos_agro,APPROX_QUANTILES(empregos_agro,100 IGNORE NULLS)[OFFSET(50)] mediana_empregos_agro,AVG(agro_share) media_agro_share,APPROX_QUANTILES(agro_share,100 IGNORE NULLS)[OFFSET(50)] mediana_agro_share,AVG(remuneracao_media) media_remuneracao,APPROX_QUANTILES(remuneracao_media,100 IGNORE NULLS)[OFFSET(50)] mediana_remuneracao,AVG(tributo_pc) media_tributo_pc,APPROX_QUANTILES(tributo_pc,100 IGNORE NULLS)[OFFSET(50)] mediana_tributo_pc,AVG(transfer_pc) media_transfer_pc,APPROX_QUANTILES(transfer_pc,100 IGNORE NULLS)[OFFSET(50)] mediana_transfer_pc,AVG(mortalidade_infantil) media_mortalidade,APPROX_QUANTILES(mortalidade_infantil,100 IGNORE NULLS)[OFFSET(50)] mediana_mortalidade,AVG(ideb_iniciais) media_ideb_iniciais,APPROX_QUANTILES(ideb_iniciais,100 IGNORE NULLS)[OFFSET(50)] mediana_ideb_iniciais,AVG(ideb_finais) media_ideb_finais,APPROX_QUANTILES(ideb_finais,100 IGNORE NULLS)[OFFSET(50)] mediana_ideb_finais FROM b GROUP BY grupo ORDER BY grupo